<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {dateTime,type Audit} from '../types'
import {session} from '../session'
import {useList} from '../useList'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
import PageState from '../components/PageState.vue'
import Pagination from '../components/Pagination.vue'
const {data,loading,error,load}=useList<Audit>();const page=ref(0);const source=ref('');const outcome=ref('');const selected=ref<Audit|null>(null)
function reload(){return load(`/audit?page=${page.value}&size=20&source=${source.value}&outcome=${outcome.value}`)};watch(page,reload);watch([source,outcome],()=>{page.value=0;void reload()});onMounted(reload)
const actionNames:Record<string,string>={'ROLE.CREATE':'创建角色','ROLE.UPDATE':'修改角色','DEPARTMENT.CREATE':'创建院系','DEPARTMENT.UPDATE':'修改院系','AUTH.LOGIN':'账号登录','AUTH.LOGOUT':'退出登录','AUTH.PASSWORD_CHANGE':'修改密码','USER.CREATE':'创建账号','USER.UPDATE':'修改账号','SPACE.CREATE':'新增空间','SPACE.UPDATE':'修改空间','NOTIFICATION.CREATE':'创建通知','NOTIFICATION.RETRY':'重试投递'}
</script>
<template><div class="page-heading"><div><div class="eyebrow">GOVERNANCE / AUDIT TRAIL</div><h1>操作审计</h1><p>让关键操作可追踪，让每一次变更有据可查。</p></div><span class="scope-note"><Icon name="shield" :size="16"/>{{session.user?.roles.includes('ADMIN')?'全平台审计':'本院系审计'}}</span></div><div class="info-strip"><Icon name="audit" :size="18"/><p>审计记录只读，保留操作者、服务来源、对象和结果。系统不在审计中接收密码、令牌或完整请求内容。</p></div><section class="panel"><div class="toolbar"><div class="filter-group"><label class="inline-label">来源<select v-model="source"><option value="">全部来源</option><option v-for="s in ['D','M1','M2','M3']" :key="s">{{s}}</option></select></label><label class="inline-label">结果<select v-model="outcome"><option value="">全部结果</option><option value="SUCCESS">成功</option><option value="FAILURE">失败</option></select></label></div><button class="text-link" @click="reload"><Icon name="refresh" :size="16"/>刷新</button></div><PageState :loading="loading" :error="error" :empty="!data.items.length" empty-text="暂无匹配的审计记录" @retry="reload"><div class="table-scroll"><table><thead><tr><th>操作</th><th>操作者</th><th>来源 / 对象</th><th>结果</th><th>发生时间</th><th class="align-right">追踪</th></tr></thead><tbody><tr v-for="event in data.items" :key="event.id"><td><strong>{{actionNames[event.action]??event.action}}</strong><small class="subtext mono">{{event.action}}</small></td><td>{{event.actorName??'服务事件'}}</td><td><span class="source-tag">{{event.source}}</span> {{event.objectType}}<small class="subtext mono short-id">{{event.objectId}}</small></td><td><span class="badge" :class="{danger:event.outcome==='FAILURE'}">{{event.outcome==='SUCCESS'?'成功':'失败'}}</span></td><td class="muted nowrap">{{dateTime(event.occurredAt)}}</td><td class="align-right"><button class="text-link" @click="selected=event">查看详情</button></td></tr></tbody></table></div><Pagination :page="page" :total="data.total" :size="20" @change="page=$event"/></PageState></section><Modal v-if="selected" title="审计详情" @close="selected=null"><div class="form-body"><dl class="detail-list"><dt>动作</dt><dd>{{selected.action}}</dd><dt>操作者</dt><dd>{{selected.actorName}}<small class="subtext mono break">{{selected.actorId}}</small></dd><dt>服务来源</dt><dd>{{selected.source}}</dd><dt>对象</dt><dd>{{selected.objectType}}<small class="subtext mono break">{{selected.objectId}}</small></dd><dt>结果</dt><dd>{{selected.outcome==='SUCCESS'?'成功':'失败'}}</dd><dt>理由码</dt><dd>{{selected.reasonCode||'无'}}</dd><dt>请求编号</dt><dd class="mono break">{{selected.requestId}}</dd><dt>审计编号</dt><dd class="mono break">{{selected.id}}</dd><dt>时间</dt><dd>{{new Date(selected.occurredAt).toLocaleString('zh-CN')}}</dd></dl><div class="form-actions"><button class="button secondary" @click="selected=null">关闭</button></div></div></Modal></template>
